def dihedral_symmetry_repair(grid, noise=8):
    """Repair noise cells by dihedral symmetry t<->31-t on the virtual centered grid; remaining unknowns in the 16x16 quadrant are filled from its constant anti-diagonal parity bands (s=i+j: per-parity, all for s=15)."""
    n=len(grid)  # symmetry t <-> 31-t on the virtual 32x32 grid (this grid is its 30x30 crop, rows/cols 0..29)
    known={}
    for i in range(n):
        for j in range(n):
            if grid[i][j]!=noise: known[(i,j)]=grid[i][j]
    groups={}
    for i in range(n):
        for j in range(n):
            key=tuple(sorted({c for c in ((31-i,j),(i,31-j),(31-i,31-j),(i,j)) if 0<=c[0]<n and 0<=c[1]<n}))
            groups.setdefault(key,[]).append((i,j))
    out=[row[:] for row in grid]
    for key,cells in groups.items():
        vs=[known[c] for c in cells if c in known]
        if vs and len(set(vs))==1:
            for c in cells: out[c[0]][c[1]]=vs[0]
    # parity-band fallback for still-unknown cells inside the 16x16 quadrant
    bandvals={}
    for i2 in range(16):
        for j2 in range(16):
            if out[i2][j2]!=noise:
                bandvals.setdefault((i2+j2,i2%2,j2%2), []).append(out[i2][j2])
    for i in range(16):
        for j in range(16):
            if out[i][j]==noise:
                grp=bandvals.get((i+j,i%2,j%2),[])
                if len(set(grp))==1 and grp:
                    out[i][j]=grp[0]
                elif i+j==15:
                    grp=[x for (s,a,b),v in bandvals.items() if s==15 for x in v]
                    if grp and len(set(grp))==1: out[i][j]=grp[0]
    return out
